mapper.sql:
WHERE true

    AND EXISTS (
        SELECT 1 FROM biz_tag_object tag_object
        WHERE tag_object.tenant_key=#{q.tagFilter.tenant} AND tag_object.object_type='ORDER'
          AND tag_object.object_id=o.id
          AND (SELECT COUNT(*) FROM biz_tag_link tag_link
               WHERE tag_link.tenant_key=tag_object.tenant_key AND tag_link.object_ref_id=tag_object.id
                 AND tag_link.tag_id IN #{tagId}
              )=#{q.tagFilter.size}
    )



        AND o.status = 'PENDING'


                AND EXISTS (
                    SELECT 1 FROM biz_approval_step approval
                    WHERE approval.biz_type = 'ORDER' AND approval.doc_id = o.id AND approval.status = 'CURRENT'
                      AND (approval.user_id = #{q.approvalScope.userId}

                            OR approval.perm = #{q.approvalScope.permission}


                            OR approval.role_id IN #{roleId}
                        )
                )

            AND false



        AND (o.create_by = #{scope.userId} OR o.sales_id = #{scope.userId} OR o.merch_id = #{scope.userId})



    AND o.status IN #{s}

AND o.order_type = #{q.orderType}
AND o.brand = #{q.brand}
AND o.sales_id = #{q.salesId}
AND o.merch_id = #{q.merchId}

    AND EXISTS (SELECT 1 FROM ord_order_item i WHERE i.order_id = o.id AND i.style_id = #{q.styleId} AND i.qty > 0)

AND o.order_date >= #{q.orderDateFrom}
AND o.order_date <= #{q.orderDateTo}
AND COALESCE(o.commit_date, o.required_date) <= #{q.dueDateTo}

    AND o.status = 'APPROVED'
    AND NOT EXISTS (SELECT 1 FROM ord_order_item i WHERE i.order_id = o.id AND i.scheduled_qty > 0)


    AND o.id IN #{id}



    AND o.id IN (
        SELECT ko.id FROM ord_order ko
        WHERE upper(ko.no) LIKE #{keywordCode} OR upper(ko.contract_no) LIKE #{keywordCode}

            OR upper(ko.no) IN #{code}

        UNION
        SELECT ki.order_id FROM sty_style ks JOIN ord_order_item ki ON ki.style_id = ks.id
        WHERE upper(ks.code) LIKE #{keywordCode}

            OR upper(ks.code) IN #{code}

    )

mapper.select:
SELECT o.* FROM ord_order o
WHERE 

        o.id IN #{id}

    false

AND o.company_id = #{companyId}
AND (


            (

                    true
                    (o.create_by = #{scope.userId} OR o.sales_id = #{scope.userId} OR o.merch_id = #{scope.userId})


                    OR (o.status = 'PENDING' AND EXISTS (
                        SELECT 1 FROM biz_approval_step approval
                        WHERE approval.biz_type = 'ORDER' AND approval.doc_id = o.id AND approval.status = 'CURRENT'
                          AND (approval.user_id = #{orderApproval.userId}

                                OR approval.perm = #{orderApproval.permission}


                                OR approval.role_id IN #{roleId}
                            )
                    ))

            )

        false


        OR EXISTS (
            SELECT 1 FROM prd_order p
            WHERE p.order_id = o.id AND p.company_id = o.company_id
              AND (

                    true
                    (p.create_by = #{scope.userId} OR p.merch_id = #{scope.userId})


                    OR (p.status = 'PENDING' AND EXISTS (
                        SELECT 1 FROM biz_approval_step approval
                        WHERE approval.biz_type = 'PRODUCTION_ORDER' AND approval.doc_id = p.id AND approval.status = 'CURRENT'
                          AND (approval.user_id = #{productionApproval.userId}

                                OR approval.perm = #{productionApproval.permission}


                                OR approval.role_id IN #{roleId}
                            )
                    ))

            )
        )



        OR EXISTS (
            SELECT 1 FROM prd_order board_order
            WHERE board_order.order_id = o.id AND board_order.company_id = o.company_id
              AND board_order.status IN ('APPROVED', 'RUNNING')

                AND (board_order.create_by = #{scope.userId} OR board_order.merch_id = #{scope.userId})

        )

)
ORDER BY o.id
